public class InnerPlaybackConfigurationLogConfigurationFactory(Action<Humidifier.MediaTailor.PlaybackConfigurationTypes.LogConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaTailor.PlaybackConfigurationTypes.LogConfiguration>
{

    internal InnerPlaybackConfigurationAdsInteractionLogFactory AdsInteractionLogFactory { get; set; }

    internal InnerPlaybackConfigurationManifestServiceInteractionLogFactory ManifestServiceInteractionLogFactory { get; set; }

    protected override Humidifier.MediaTailor.PlaybackConfigurationTypes.LogConfiguration Create()
    {
        var logConfigurationResult = CreateLogConfiguration();
        factoryAction?.Invoke(logConfigurationResult);

        return logConfigurationResult;
    }

    private Humidifier.MediaTailor.PlaybackConfigurationTypes.LogConfiguration CreateLogConfiguration()
    {
        var logConfigurationResult = new Humidifier.MediaTailor.PlaybackConfigurationTypes.LogConfiguration();

        return logConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaTailor.PlaybackConfigurationTypes.LogConfiguration result)
    {
        base.CreateChildren(result);

        result.AdsInteractionLog ??= AdsInteractionLogFactory?.Build();
        result.ManifestServiceInteractionLog ??= ManifestServiceInteractionLogFactory?.Build();
    }

} // End Of Class

